head.script:
//
(function () {
  var theme = 'light';
  try { theme = localStorage.getItem('pxl-theme') === 'dark' ? 'dark' : 'light'; } catch (e) {}
  document.documentElement.setAttribute('data-theme', theme);
})();
//

head.b:skin:
/* ==========================================================================
   Theme variables - light (default) and dark ([data-theme="dark"] on <html>)
   ========================================================================== */
:root {
  --accent-lime: #32CD32;
  --accent-strong: #22a822;
  --accent-ink: #04120a;
  --accent-soft: rgba(50, 205, 50, 0.12);
  --accent-glow: none;

  --bg-color: #f8f9fa;
  --surface: #ffffff;            /* header, hero, footer, sidebar */
  --card-bg: #ffffff;
  --card-head: #f4f5f7;
  --input-bg: #ffffff;
  --text-main: #15181d;
  --text-muted: #5f6772;
  --border-color: #e3e6eb;
  --shadow: 0 4px 12px rgba(0, 0, 0, 0.05);
  --shadow-hover: 0 10px 24px rgba(0, 0, 0, 0.08);
  --skeleton: #e9ecef;
  --skeleton-hi: #f4f5f7;
  --live: #e11d48;
  --live-soft: rgba(225, 29, 72, 0.10);

  --font-family: 'Cairo', Tahoma, 'Segoe UI', sans-serif;
  --spacing: 0.75rem;
  --radius: 0.75rem;
  --container: 1200px;
  --header-h: 64px;
}

[data-theme="dark"] {
  --accent-lime: #3ee63e;
  --accent-strong: #32CD32;
  --accent-soft: rgba(62, 230, 62, 0.14);
  --accent-glow: 0 0 18px rgba(62, 230, 62, 0.35);

  --bg-color: #080b10;           /* deep black / slate */
  --surface: #0f141b;
  --card-bg: #171e28;            /* dark gray cards */
  --card-head: #1d2532;
  --input-bg: #121821;
  --text-main: #f2f5f8;
  --text-muted: #9aa4b1;
  --border-color: rgba(255, 255, 255, 0.08);
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 22px rgba(0, 0, 0, 0.35);
  --shadow-hover: 0 0 0 1px rgba(62, 230, 62, 0.35), 0 14px 32px rgba(0, 0, 0, 0.5);
  --skeleton: #1b222d;
  --skeleton-hi: #232c39;
  --live: #ff3b5c;
  --live-soft: rgba(255, 59, 92, 0.14);
  color-scheme: dark;
}

/* ==========================================================================
   Base
   ========================================================================== */
*, *::before, *::after { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg-color);
  color: var(--text-main);
  font-family: var(--font-family);
  line-height: 1.6;
  overflow-x: hidden;
  transition: background-color .25s ease, color .25s ease;
}
a { color: var(--accent-strong); text-decoration: none; }
[data-theme="dark"] a { color: var(--accent-lime); }
a:hover { text-decoration: underline; }
img { max-width: 100%; }
button { font: inherit; color: inherit; cursor: pointer; }
:focus-visible { outline: 2px solid var(--accent-lime); outline-offset: 2px; border-radius: 6px; }
.container { width: 100%; max-width: var(--container); margin-inline: auto; padding-inline: 16px; }
.section, .widget, .widget-content { margin: 0; }

/* ==========================================================================
   Header (logo, nav, search, theme toggle, mobile menu)
   ========================================================================== */
header.site-header {
  position: sticky; top: 0; z-index: 1000;
  background: var(--surface);
  border-bottom: 1px solid var(--border-color);
  box-shadow: var(--shadow);
}
[data-theme="dark"] header.site-header {
  background: rgba(15, 20, 27, 0.82);
  -webkit-backdrop-filter: saturate(160%) blur(14px);
  backdrop-filter: saturate(160%) blur(14px);
}
.header-inner {
  min-height: var(--header-h);
  display: flex; align-items: center; justify-content: space-between; gap: var(--spacing);
}
.logo h1, .logo .logo-text {
  margin: 0; font-size: 1.45rem; font-weight: 800; line-height: 1;
  color: var(--text-main); letter-spacing: .3px; white-space: nowrap; direction: ltr;
}
.logo a { color: inherit; text-decoration: none; }
.logo b { color: var(--accent-strong); }
[data-theme="dark"] .logo b { color: var(--accent-lime); text-shadow: 0 0 14px rgba(62, 230, 62, .45); }

nav.main-nav { display: flex; flex-wrap: wrap; justify-content: center; gap: 4px; }
nav.main-nav a {
  padding: 8px 14px; border-radius: 999px;
  color: var(--text-muted); font-weight: 700; text-decoration: none;
  transition: background-color .2s, color .2s;
}
nav.main-nav a:hover, nav.main-nav a.is-active { color: var(--text-main); background: var(--accent-soft); }

.header-actions { display: flex; align-items: center; gap: 6px; }
.icon-btn {
  width: 40px; height: 40px; display: grid; place-items: center;
  border-radius: 12px; border: 1px solid var(--border-color);
  background: var(--card-bg); color: var(--text-main);
  transition: border-color .2s, box-shadow .2s;
}
.icon-btn:hover { border-color: var(--accent-lime); box-shadow: var(--accent-glow); }
.icon-btn svg { width: 19px; height: 19px; }
.icon-sun { display: none; }
[data-theme="dark"] .icon-sun { display: block; }
[data-theme="dark"] .icon-moon { display: none; }
.mobile-menu { display: none; }

/* ==========================================================================
   Home: hero + date navigation
   ========================================================================== */
.home-layout { display: grid; grid-template-columns: 1fr; gap: 20px; padding-block: 20px 40px; }
@media (min-width: 1024px) { .home-layout { grid-template-columns: minmax(0, 1fr) 300px; } }

.hero {
  background: var(--surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: calc(2 * var(--spacing));
  text-align: center;
}
[data-theme="dark"] .hero { background: linear-gradient(135deg, #0f141b 0%, #111d14 100%); }
.hero h1 { font-size: 1.8rem; margin: 0 0 6px; font-weight: 800; }
.hero p { margin: 0 0 var(--spacing); color: var(--text-muted); }
.live-indicator {
  display: inline-flex; align-items: center; gap: 8px;
  background: var(--live-soft); color: var(--live);
  padding: 0.25rem 0.75rem; border-radius: 999px; font-weight: 800; font-size: .9rem;
}
.live-indicator::before, .live-dot {
  content: ''; display: inline-block; width: 8px; height: 8px; border-radius: 50%;
  background: var(--live); animation: pxl-pulse 1.6s infinite;
}
@keyframes pxl-pulse {
  0% { box-shadow: 0 0 0 0 rgba(225, 29, 72, .6); }
  70% { box-shadow: 0 0 0 8px rgba(225, 29, 72, 0); }
  100% { box-shadow: 0 0 0 0 rgba(225, 29, 72, 0); }
}
.date-nav { margin-top: var(--spacing); display: flex; justify-content: center; align-items: center; gap: var(--spacing); }
.date-nav button {
  width: 38px; height: 38px; border-radius: 50%;
  border: 1px solid var(--border-color); background: var(--card-bg); color: var(--text-main);
}
.date-nav button:hover { border-color: var(--accent-lime); color: var(--accent-strong); }
#todayLabel { min-width: 120px; font-weight: 800; direction: ltr; }

/* ==========================================================================
   Home: match center (tabs, search, cards)
   ========================================================================== */
.match-center { margin-top: 20px; }
.tabs { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin: var(--spacing) 0; }
.tab {
  cursor: pointer; padding: 8px 18px; border-radius: 999px;
  background: var(--card-bg); color: var(--text-muted);
  border: 1px solid var(--border-color); font-weight: 700;
  transition: background-color .2s, color .2s, border-color .2s;
}
.tab:hover { border-color: var(--accent-lime); color: var(--text-main); }
.tab.active { background: var(--accent-lime); color: var(--accent-ink); border-color: var(--accent-lime); box-shadow: var(--accent-glow); }
#matchSearch {
  width: 100%; padding: 12px 14px; margin-bottom: var(--spacing);
  border-radius: var(--radius); border: 1px solid var(--border-color);
  background: var(--input-bg); color: var(--text-main); font: inherit;
}
#matchSearch::placeholder { color: var(--text-muted); }
#matchSearch:focus { outline: none; border-color: var(--accent-lime); box-shadow: 0 0 0 3px var(--accent-soft); }

.matches { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: var(--spacing); }

/* Match card (same structure as before: league header / home - center - away / channel + commentator) */
.match-card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}
.match-card.is-link { cursor: pointer; }
.match-card:hover { border-color: rgba(50, 205, 50, .5); box-shadow: var(--shadow-hover); }
.match-card.is-link:hover { transform: translateY(-3px); }
.match-card.is-live { border-color: rgba(225, 29, 72, .35); }

.match-card__league {
  display: flex; justify-content: flex-end;
  padding: 8px 16px; border-bottom: 1px solid var(--border-color);
  background: var(--card-head);
  font-size: .75rem; color: var(--text-muted); font-weight: 700;
}
.match-card__body { display: flex; align-items: center; padding: 16px; }
.match-team { width: 33.333%; text-align: center; min-width: 0; }
.match-team img {
  width: 48px; height: 48px; margin-inline: auto; display: block; object-fit: contain;
  border-radius: 50%; background: var(--card-head); padding: 4px;
}
.match-team__name {
  margin-top: 8px; font-size: .875rem; font-weight: 800;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.match-mid { width: 33.333%; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.match-badge {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  padding: 4px 12px; border-radius: 8px;
  background: var(--card-head); font-size: 1.125rem; font-weight: 800;
}
.match-badge .time { direction: ltr; }
/* Flex follows RTL: first number = home team, on the home team's side */
.match-badge .sep { color: var(--text-muted); font-weight: 600; }
.match-card.is-live .match-badge { color: var(--live); }
.match-status { margin-top: 4px; font-size: .75rem; color: var(--text-muted); }
.match-card.is-live .match-status { color: var(--live); font-weight: 800; }

.match-card__footer {
  display: flex; padding: 8px 16px;
  border-top: 1px solid var(--border-color);
  background: var(--card-head);
  font-size: .75rem; color: var(--text-muted);
}
.match-meta { display: flex; align-items: center; gap: 4px; width: 50%; min-width: 0; }
.match-meta--channel { border-inline-end: 1px solid var(--border-color); }
.match-meta--commentator { justify-content: center; }
.match-meta svg { width: 14px; height: 14px; flex-shrink: 0; color: var(--accent-strong); }
[data-theme="dark"] .match-meta svg { color: var(--accent-lime); }
.match-meta span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* Skeleton / empty / error (same classes as before) */
.skeleton { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--radius); padding: 16px; animation: pulse 1.5s infinite; }
.skeleton .bar { height: 12px; border-radius: 6px; background: var(--skeleton); }
.skeleton .row { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 14px; }
.skeleton .avatar { width: 48px; height: 48px; background: var(--skeleton); border-radius: 50%; }
.skeleton .score-bar { width: 64px; height: 28px; border-radius: 8px; background: var(--skeleton-hi); }
@keyframes pulse { 0% { opacity: .6; } 50% { opacity: 1; } 100% { opacity: .6; } }
.empty, .error {
  grid-column: 1 / -1; text-align: center; padding: calc(2 * var(--spacing)); color: var(--text-muted);
  background: var(--card-bg); border: 1px dashed var(--border-color); border-radius: var(--radius);
}
.error button {
  margin-top: var(--spacing); padding: 0.5rem 1.25rem; border: none; border-radius: 999px;
  background: var(--accent-lime); color: var(--accent-ink); font-weight: 800;
}

/* ==========================================================================
   Home: leagues strip + sidebar
   ========================================================================== */
.leagues { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--spacing); margin: 24px 0 0; }
.league {
  background: var(--card-bg); color: var(--text-main);
  border: 1px solid var(--border-color); border-radius: 999px;
  padding: 8px 16px; font-weight: 700; box-shadow: var(--shadow);
}
.sidebar {
  align-self: start;
  background: var(--surface); border: 1px solid var(--border-color);
  border-radius: var(--radius); box-shadow: var(--shadow);
  padding: 16px;
}
@media (min-width: 1024px) { .sidebar { position: sticky; top: calc(var(--header-h) + 16px); } }
.sidebar h2 { margin: 0 0 10px; font-size: 1.05rem; display: flex; align-items: center; gap: 8px; }
.sidebar h2::before { content: ''; width: 4px; height: 18px; border-radius: 3px; background: var(--accent-lime); }
.sidebar ul { margin: 0; padding: 0; list-style: none; display: grid; gap: 6px; }
.sidebar li a { display: block; padding: 8px 10px; border-radius: 8px; color: var(--text-main); }
.sidebar li a:hover { background: var(--accent-soft); text-decoration: none; }

/* ==========================================================================
   Match post: live stream arena (player + ads)
   ========================================================================== */
.arena { padding-block: 20px 4px; }
.arena-head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; margin-bottom: 12px; }
.arena-head h1 { margin: 0; font-size: 1.35rem; line-height: 1.45; font-weight: 800; }
.arena-grid { display: grid; grid-template-columns: 1fr; gap: 16px; align-items: start; }
.arena-center { min-width: 0; display: grid; gap: 14px; }
@media (min-width: 1200px) { .arena-grid { grid-template-columns: 160px minmax(0, 1fr) 160px; } }

.player-wrapper {
  position: relative; width: 100%;
  aspect-ratio: 16 / 9;
  border-radius: var(--radius); overflow: hidden; background: #000;
  border: 1px solid var(--border-color); box-shadow: var(--shadow);
}
[data-theme="dark"] .player-wrapper { box-shadow: 0 0 0 1px rgba(62, 230, 62, .25), 0 0 40px rgba(62, 230, 62, .12); }
@supports not (aspect-ratio: 16 / 9) { .player-wrapper { height: 0; padding-top: 56.25%; } }
.player-wrapper iframe, .player-wrapper video, .player-placeholder {
  position: absolute; inset: 0; width: 100%; height: 100%; border: 0;
}
.player-placeholder {
  display: grid; place-items: center; align-content: center; gap: 10px;
  text-align: center; color: #cfd6dd; font-weight: 700;
  background: radial-gradient(ellipse at center, #10161d 0%, #000 75%);
}
.player-placeholder svg { width: 54px; height: 54px; color: #32CD32; }

.ad-slot {
  display: grid; place-items: center; width: 100%;
  border-radius: 10px; border: 1px dashed var(--border-color);
  background: repeating-linear-gradient(45deg, var(--card-head), var(--card-head) 10px, var(--card-bg) 10px, var(--card-bg) 20px);
  color: var(--text-muted); font-size: .8rem; overflow: hidden;
}
.ad-slot .widget, .ad-slot .widget-content { width: 100%; display: grid; place-items: center; }
.ad-slot--h { min-height: 100px; }
.ad-slot--v { min-height: 600px; }
.ad-side { display: none; }
.ad-label { padding: 8px; }
@media (min-width: 768px) { .ad-slot--h { min-height: 90px; } }
@media (min-width: 1200px) { .ad-side { display: grid; position: sticky; top: calc(var(--header-h) + 16px); } }

/* Post / page content */
.content-area { padding-block: 20px 40px; }
.post-full {
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius); box-shadow: var(--shadow); padding: 22px;
}
.post-full h1, .post-full h2.post-title { margin: 0 0 6px; font-size: 1.5rem; font-weight: 800; line-height: 1.45; }
.post-meta { color: var(--text-muted); font-size: .88rem; margin-bottom: 16px; }
.post-body { overflow-wrap: anywhere; }
.post-body img { border-radius: 10px; height: auto; }
.post-body [data-stream-src] { display: none; }
.post-list { display: grid; gap: 12px; }
.post-list a.post-item {
  display: block; padding: 14px 16px; border-radius: var(--radius);
  background: var(--card-bg); border: 1px solid var(--border-color); box-shadow: var(--shadow);
  color: var(--text-main); font-weight: 700;
}
.post-list a.post-item:hover { border-color: var(--accent-lime); text-decoration: none; }

/* ==========================================================================
   Footer
   ========================================================================== */
footer.site-footer {
  background: var(--surface); border-top: 1px solid var(--border-color);
  padding: calc(1.5 * var(--spacing)) var(--spacing); text-align: center;
  font-size: 0.875rem; color: var(--text-muted);
}
footer.site-footer p { margin: 0 0 8px; }
footer.site-footer nav { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--spacing); }
footer.site-footer nav a { color: var(--text-muted); }
footer.site-footer nav a:hover { color: var(--accent-strong); }

/* ==========================================================================
   Responsive
   ========================================================================== */
@media (max-width: 860px) {
  .mobile-menu { display: grid; }
  nav.main-nav {
    position: fixed; inset: var(--header-h) 0 auto 0;
    flex-direction: column; gap: 2px;
    background: var(--surface); border-bottom: 1px solid var(--border-color); box-shadow: var(--shadow);
    padding: 10px 16px 16px;
    opacity: 0; visibility: hidden; transform: translateY(-8px);
    transition: opacity .2s, transform .2s, visibility .2s;
  }
  nav.main-nav.is-open { opacity: 1; visibility: visible; transform: none; }
  nav.main-nav a { padding: 12px 14px; border-radius: 10px; }
}
@media (max-width: 768px) {
  .matches { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .hero h1 { font-size: 1.5rem; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

head.b:template-skin:
body#layout { background: #f6f7f9; font-family: Arial, sans-serif; }
body#layout .header-inner, body#layout .hero, body#layout .match-center, body#layout .leagues,
body#layout .sidebar, body#layout .arena-head, body#layout .player-wrapper { display: none; }
body#layout .arena-grid { display: flex; gap: 8px; }
body#layout .arena-center { flex: 1; }
body#layout .ad-side { display: block; width: 160px; }

body.script:
//
(function () {
  var root = document.documentElement;
  var toggle = document.getElementById('theme-toggle');
  var metaTheme = document.querySelector('meta[name="theme-color"]');

  function applyTheme(theme) {
    root.setAttribute('data-theme', theme);
    toggle.setAttribute('aria-pressed', theme === 'dark' ? 'true' : 'false');
    if (metaTheme) metaTheme.setAttribute('content', theme === 'dark' ? '#080b10' : '#32CD32');
  }
  applyTheme(root.getAttribute('data-theme') === 'dark' ? 'dark' : 'light');

  toggle.addEventListener('click', function () {
    var next = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
    applyTheme(next);
    try { localStorage.setItem('pxl-theme', next); } catch (e) { /* private mode: not saved */ }
  });

  var menuBtn = document.getElementById('mobile-menu');
  var nav = document.getElementById('main-nav');
  function setMenu(open) {
    nav.classList.toggle('is-open', open);
    menuBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
  }
  menuBtn.addEventListener('click', function () { setMenu(!nav.classList.contains('is-open')); });
  nav.addEventListener('click', function (e) { if (e.target.closest('a')) setMenu(false); });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') setMenu(false); });

  var year = document.getElementById('pxl-year');
  if (year) year.textContent = String(new Date().getFullYear());
})();
//

b:if.script:
//
(function () {
  var slot = document.getElementById('px-player');
  var body = document.getElementById('px-post-body');
  if (!slot || !body) return;

  var frame = null;
  var marker = body.querySelector('[data-stream-src]');
  if (marker) {
    var src = marker.getAttribute('data-stream-src') || '';
    if (/^https:\/\//i.test(src)) {
      frame = document.createElement('iframe');
      frame.src = src;
    }
    marker.remove();
  } else {
    frame = body.querySelector('iframe');
  }
  if (!frame) return;      // no stream in this post: keep "starting soon"

  frame.setAttribute('allow', 'autoplay; fullscreen; encrypted-media; picture-in-picture');
  frame.setAttribute('allowfullscreen', 'true');
  frame.setAttribute('title', document.title);
  frame.removeAttribute('width');
  frame.removeAttribute('height');
  frame.removeAttribute('style');
  slot.textContent = '';
  slot.appendChild(frame);
})();
