(function () {
  'use strict';

  // ------------------------------------------------------------
  // Configuration
  // ------------------------------------------------------------
  var WORKER_BASE = 'https://<YOUR_WORKER_SUBDOMAIN>.workers.dev/api';   // your Worker; demo data until set
  var MAX_RETRIES = 2;
  var REFRESH_MS = 60 * 1000;          // refresh today's scores every minute (visible tab only)

  // Fallback for missing / broken team logos. Replace with your own image URL if you like
  // (e.g. 'https://your-cdn/default-team.png'); the default is an inline shield icon.
  var DEFAULT_LOGO_URL = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64">' +
    '<path d="M32 4 8 12v18c0 15 10.5 25.5 24 30 13.5-4.5 24-15 24-30V12L32 4z" fill="#32CD32" fill-opacity=".18" stroke="#32CD32" stroke-width="3"/>' +
    '<circle cx="32" cy="30" r="8" fill="none" stroke="#32CD32" stroke-width="3"/></svg>');
  window.PXL_DEFAULT_LOGO = DEFAULT_LOGO_URL;   // used by the img onerror handler

  // Where a click on a match card goes. '' = cards are not links (unless the API sends m.url).
  // Example for a Blogger page that reads ?id=: '/p/match.html'
  var MATCH_PAGE_URL = '';

  var IS_DEMO = WORKER_BASE.indexOf('<YOUR_WORKER_SUBDOMAIN>') !== -1;

  // ------------------------------------------------------------
  // Helpers
  // ------------------------------------------------------------
  var ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  function esc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return ESC[c]; }); }
  function safeUrl(u) {
    var s = String(u == null ? '' : u).trim();
    return /^https?:\/\//i.test(s) ? s : '';
  }

  // fetch with timeout & retry (from your draft)
  async function fetchJson(url, attempts) {
    if (attempts == null) attempts = MAX_RETRIES;
    var controller = new AbortController();
    var timeout = setTimeout(function () { controller.abort(); }, 8000);
    try {
      var resp = await fetch(url, { signal: controller.signal, headers: { Accept: 'application/json' } });
      if (!resp.ok) throw new Error('HTTP ' + resp.status);
      return await resp.json();
    } catch (e) {
      if (attempts > 1) return fetchJson(url, attempts - 1);
      throw e;
    } finally {
      clearTimeout(timeout);
    }
  }

  // Dates always in Africa/Cairo
  function cairoDateString(dateObj) {
    var parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo' }).formatToParts(dateObj);
    var get = function (t) { return parts.find(function (p) { return p.type === t; }).value; };
    return get('year') + '-' + get('month') + '-' + get('day');
  }
  function cairoTime(iso) {
    var d = new Date(iso);
    if (isNaN(d)) return '';
    return new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit', hour12: false }).format(d);
  }

  // Normalize one match from the Worker (models.js fields + the fields your draft used)
  function category(m) {
    var s = String(m.statusCategory || m.status || '').toLowerCase();
    if (/^(live|in[_ ]?play|1h|2h|ht|et|playing|مباشر)/.test(s)) return 'live';
    if (/^(finished|ended|ft|aet|pen|انتهت)/.test(s)) return 'finished';
    return 'upcoming';
  }
  function normalize(m) {
    var b = m.broadcast || {};
    var sc = m.score || {};
    return {
      id: m.id,
      url: safeUrl(m.url),
      league: m.league || '',
      cat: category(m),
      statusText: m.statusText || m.statusLabel || '',
      time: m.time || cairoTime(m.startTime) || '--:--',
      home: { name: (m.homeTeam && m.homeTeam.name) || '', logo: safeUrl(m.homeTeam && m.homeTeam.logo) },
      away: { name: (m.awayTeam && m.awayTeam.name) || '', logo: safeUrl(m.awayTeam && m.awayTeam.logo) },
      scoreHome: sc.home != null ? sc.home : 0,
      scoreAway: sc.away != null ? sc.away : 0,
      channel: b.channel || m.channel || 'غير متوفر',
      commentator: b.commentator || m.commentator || 'غير متوفر'
    };
  }

  // ------------------------------------------------------------
  // UI state & rendering
  // ------------------------------------------------------------
  var container = document.getElementById('matches-api-container');
  var tabs = document.querySelectorAll('#matchTabs .tab');
  var searchInput = document.getElementById('matchSearch');
  var todayLabel = document.getElementById('todayLabel');
  if (!container) return;

  var state = { date: new Date(), filter: 'all', rawMatches: [], loading: true, error: null, requestId: 0 };

  var ICON_TV = '<svg aria-hidden="true" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="2" y="7" width="20" height="15" rx="2" ry="2" stroke-width="2"></rect><polyline points="17 2 12 7 7 2" stroke-width="2"></polyline></svg>';
  var ICON_MIC = '<svg aria-hidden="true" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11a7 7 0 01-14 0m7 7v4m-4 0h8M12 1a3 3 0 00-3 3v8a3 3 0 006 0V4a3 3 0 00-3-3z"></path></svg>';

  function logoImg(team) {
    // Missing URL -> default logo; broken URL -> onerror swaps in the default (once, no loop)
    return `<img src="${esc(team.logo || DEFAULT_LOGO_URL)}" alt="${esc(team.name)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.onerror=null;this.src=window.PXL_DEFAULT_LOGO">`;
  }

  function cardLink(m) {
    if (m.url) return m.url;
    if (MATCH_PAGE_URL && m.id != null) return MATCH_PAGE_URL + '?id=' + encodeURIComponent(m.id);
    return '';
  }

  function scoreHtml(m) {
    return `<span>${esc(m.scoreHome)}</span><span class="sep">-</span><span>${esc(m.scoreAway)}</span>`;
  }

  function createCard(m) {
    var isLive = m.cat === 'live';
    var isFinished = m.cat === 'finished';
    var link = cardLink(m);

    var center = isLive
      ? `<div class="match-badge">${scoreHtml(m)}<span class="live-dot"></span></div>
         <div class="match-status">${esc(m.statusText || 'مباشر')}</div>`
      : `<div class="match-badge">${isFinished ? scoreHtml(m) : `<span class="time">${esc(m.time)}</span>`}</div>
         <div class="match-status">${esc(m.statusText || (isFinished ? 'انتهت' : 'لم تبدأ'))}</div>`;

    return `
      <div class="match-card${isLive ? ' is-live' : ''}${link ? ' is-link' : ''}"${link ? ` data-href="${esc(link)}" role="link" tabindex="0"` : ''}>
        <!-- Header -->
        <div class="match-card__league"><span>${esc(m.league)}</span></div>

        <!-- Middle (Teams & Time) -->
        <div class="match-card__body">
          <!-- Right: Home Team -->
          <div class="match-team">
            ${logoImg(m.home)}
            <div class="match-team__name">${esc(m.home.name)}</div>
          </div>

          <!-- Center: Match Time / Status / Score Badge -->
          <div class="match-mid">${center}</div>

          <!-- Left: Away Team -->
          <div class="match-team">
            ${logoImg(m.away)}
            <div class="match-team__name">${esc(m.away.name)}</div>
          </div>
        </div>

        <!-- Bottom Footer (Channel & Commentator) -->
        <div class="match-card__footer">
          <div class="match-meta match-meta--channel">${ICON_TV}<span>${esc(m.channel)}</span></div>
          <div class="match-meta match-meta--commentator">${ICON_MIC}<span>${esc(m.commentator)}</span></div>
        </div>
      </div>`;
  }

  function renderSkeleton() {
    var one = '<div class="skeleton"><div class="bar" style="width:40%"></div><div class="row"><div class="avatar"></div><div class="score-bar"></div><div class="avatar"></div></div></div>';
    container.innerHTML = new Array(7).join(one);
  }
  function renderEmpty() {
    container.innerHTML = '<p class="empty">لا توجد مباريات في هذا التاريخ.</p>';
  }
  function renderError(msg) {
    container.innerHTML = `<div class="error"><p>${esc(msg)}</p><button type="button">إعادة المحاولة</button></div>`;
    container.querySelector('.error button').addEventListener('click', function () { loadMatches(); });
  }
  function applyFilters(list) {
    var filtered = state.filter === 'all' ? list : list.filter(function (m) { return m.cat === state.filter; });
    var q = searchInput ? searchInput.value.trim().toLowerCase() : '';
    if (q) {
      filtered = filtered.filter(function (m) {
        return m.home.name.toLowerCase().indexOf(q) !== -1 || m.away.name.toLowerCase().indexOf(q) !== -1;
      });
    }
    return filtered;
  }
  function render() {
    if (state.loading) { renderSkeleton(); return; }
    if (state.error) { renderError(state.error); return; }
    var list = applyFilters(state.rawMatches);
    if (!list.length) { renderEmpty(); return; }
    container.innerHTML = list.map(createCard).join('');
  }
  function setState(updates) {
    for (var k in updates) state[k] = updates[k];
    render();
  }

  // Card clicks (delegated; only for cards that have a link)
  function openCard(e) {
    var card = e.target.closest('.match-card.is-link');
    if (card) window.location.href = card.getAttribute('data-href');
  }
  container.addEventListener('click', openCard);
  container.addEventListener('keydown', function (e) { if (e.key === 'Enter') openCard(e); });

  // ------------------------------------------------------------
  // Data loading
  // ------------------------------------------------------------
  async function loadMatches(silent) {
    var currentRequest = ++state.requestId;
    if (!silent) setState({ loading: true, error: null });
    var iso = cairoDateString(state.date);
    try {
      var data = IS_DEMO ? demoData() : await fetchJson(WORKER_BASE + '/matches?date=' + iso);
      if (state.requestId !== currentRequest) return;          // a newer request is running
      setState({ loading: false, error: null, rawMatches: (data.matches || []).map(normalize) });
    } catch (e) {
      if (state.requestId !== currentRequest) return;
      console.warn('[PX League] matches:', e);
      if (silent && state.rawMatches.length) return;            // keep the last good data on refresh errors
      setState({ loading: false, error: 'فشل تحميل المباريات – يرجى المحاولة مرة أخرى.', rawMatches: [] });
    }
  }

  // ------------------------------------------------------------
  // UI wiring (tabs, date navigation, search)
  // ------------------------------------------------------------
  function selectTab(t) {
    tabs.forEach(function (tc) { tc.classList.remove('active'); tc.setAttribute('aria-selected', 'false'); });
    t.classList.add('active');
    t.setAttribute('aria-selected', 'true');
    state.filter = t.getAttribute('data-tab') || 'all';
    render();
  }
  tabs.forEach(function (t) {
    t.addEventListener('click', function () { selectTab(t); });
    t.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); selectTab(t); } });
  });

  function changeDay(delta) {
    state.date = new Date(state.date.getTime() + delta * 24 * 60 * 60 * 1000);
    todayLabel.textContent = cairoDateString(state.date);
    loadMatches();
  }
  document.getElementById('prevDay').addEventListener('click', function () { changeDay(-1); });
  document.getElementById('nextDay').addEventListener('click', function () { changeDay(+1); });

  if (searchInput) searchInput.addEventListener('input', render);

  // "مباشر" menu link (#live) opens the live tab
  if (location.hash === '#live') { var liveTab = document.querySelector('#matchTabs .tab[data-tab="live"]'); if (liveTab) selectTab(liveTab); }

  // Initialisation
  todayLabel.textContent = cairoDateString(state.date);
  loadMatches();
  setInterval(function () {
    if (!document.hidden && cairoDateString(state.date) === cairoDateString(new Date())) loadMatches(true);
  }, REFRESH_MS);

  // Demo data (only while WORKER_BASE is not configured)
  function demoData() {
    return { matches: [
      { id: 1, league: 'الدوري الإسباني', status: 'live', statusText: "مباشر 67'", homeTeam: { name: 'ريال مدريد', logo: '' }, awayTeam: { name: 'برشلونة', logo: 'https://invalid.example/broken.png' }, score: { home: 2, away: 1 }, broadcast: { channel: 'beIN Sports 1', commentator: 'عصام الشوالي' } },
      { id: 2, league: 'الدوري الإنجليزي الممتاز', status: 'upcoming', time: '22:00', homeTeam: { name: 'مانشستر سيتي' }, awayTeam: { name: 'ليفربول' }, broadcast: { channel: 'beIN Sports 2', commentator: 'حفيظ دراجي' } },
      { id: 3, league: 'الدوري المصري الممتاز', status: 'ended', homeTeam: { name: 'الأهلي' }, awayTeam: { name: 'الزمالك' }, score: { home: 1, away: 1 }, broadcast: { channel: 'ON Sport', commentator: 'مدحت شلبي' } }
    ] };
  }
})();
//
